import {requestCapture} from './capture.mjs?v=13';
import {bounded} from './media-import.mjs?v=13';
import {setAudioMode} from './audio-output.mjs?v=13';
import {createPcmRecorder} from './pcm-capture.mjs?v=13';
import {encodeWav} from './audio-utils.mjs?v=13';
import {snapshot,reading,formatMs,explainPlacement,summarizeTrials,loadRecordingLogs,LOG_KEY} from './latency-diagnostics.mjs';
import {makeClick} from './latency-analysis.mjs';
const $=id=>document.getElementById(id),SESSION_KEY='pocket-booth-developer-measurements-v1';
let stream,context,operation,probePassed=false,currentSession,sessions=[],audioUrls=[],activeSources=[],lastStorageError='';
try{const saved=JSON.parse(localStorage.getItem(SESSION_KEY)||'[]');if(Array.isArray(saved))sessions=saved.slice(-10);}catch{lastStorageError='診断結果の保存領域を利用できません。JSONを保存してください。';}
function persist(){try{localStorage.setItem(SESSION_KEY,JSON.stringify(sessions.slice(-10)));lastStorageError='';}catch{lastStorageError='診断結果を端末に保存できません。JSONを保存してください。';}$('storageStatus').textContent=lastStorageError;}
const ms=value=>Number.isFinite(value)?`${(value*1000).toFixed(2)} ms`:'取得不可';
function rowList(target,rows){const dl=document.createElement('dl');for(const [name,value]of rows){const dt=document.createElement('dt'),dd=document.createElement('dd');dt.textContent=name;dd.textContent=value;dl.append(dt,dd);}target.replaceChildren(dl);}
function showSnapshot(data){rowList($('snapshot'),[['Context',`${data.contextId} / ${data.state}`],['サンプルレート',`${data.sampleRate} Hz`],['マイク',data.input.label||'取得不可'],['入力latency',formatMs(data.inputLatency)],['出力latency',formatMs(data.outputLatency)],['baseLatency',formatMs(data.baseLatency)],['出力装置の実名','取得不可（APIで経路検証不可・自己申告を使用）']]);}
function update(){const busy=!!operation,connected=!!stream&&context?.state==='running';for(const id of ['route','routeNote','input','duration','coupled','routeConfirmed'])$(id).disabled=busy;$('connect').disabled=busy;$('disconnect').disabled=busy||!stream;$('probe').disabled=busy||!connected||!$('route').value||!$('coupled').checked||!$('routeConfirmed').checked;$('measure').disabled=busy||!connected||!probePassed;$('cancel').disabled=!busy;$('clear').disabled=busy;$('download').disabled=busy;}
function abortError(message='測定を中止しました'){return new DOMException(message,'AbortError');}
function stopSources(){for(const source of activeSources){try{source.stop();source.disconnect();}catch{}}activeSources=[];}
async function release(){probePassed=false;stopSources();const oldStream=stream,old=context;stream=undefined;context=undefined;oldStream?.getTracks().forEach(t=>t.stop());setAudioMode('playback');try{await old?.close();}catch{}$('connection').textContent='マイクを解放しました';update();}
function invalidate(message){operation?.abort(abortError(message));probePassed=false;$('probeResult').textContent=message;release();}
function fingerprint(data){return JSON.stringify({label:data.input.label,settings:data.input.settings,sampleRate:data.sampleRate,contextId:data.contextId});}
function environment(){return {userAgent:navigator.userAgent,standalone:!!navigator.standalone,secureContext:isSecureContext,origin:location.origin};}
function declaredRoute(){return {declared:$('route').value,notes:$('routeNote').value,verification:'user-reported-only',userConfirmed:$('routeConfirmed').checked,acousticSetupConfirmed:$('coupled').checked};}
function checkSignal(signal){if(signal.aborted)throw signal.reason||abortError();}
function wait(seconds,signal,ctx){return new Promise((resolve,reject)=>{const start=performance.now(),timer=setInterval(()=>{if(signal.aborted)return finish(signal.reason||abortError());if(document.hidden||ctx.state!=='running')return finish(abortError('音声Contextの中断・画面移動のため測定無効'));if(performance.now()-start>=seconds*1000)finish();},50);const abort=()=>finish(signal.reason||abortError());function finish(error){clearInterval(timer);signal.removeEventListener('abort',abort);error?reject(error):resolve();}signal.addEventListener('abort',abort,{once:true});});}
function analysis(data,signal){return new Promise((resolve,reject)=>{const worker=new Worker(new URL('./latency-worker.mjs',import.meta.url),{type:'module'}),timeout=setTimeout(()=>finish(new Error('クリック解析が時間内に完了しませんでした')),30000);const abort=()=>finish(signal.reason||abortError());function finish(error,result){clearTimeout(timeout);signal.removeEventListener('abort',abort);worker.terminate();error?reject(error):resolve(result);}worker.onmessage=({data})=>data.error?finish(new Error(data.error)):finish(null,data.result);worker.onerror=()=>finish(new Error('解析Workerを実行できません'));signal.addEventListener('abort',abort,{once:true});worker.postMessage(data,[data.samples.buffer,data.reference.buffer]);});}
function preview(blob,reference){for(const url of audioUrls)URL.revokeObjectURL(url);audioUrls=[URL.createObjectURL(reference),URL.createObjectURL(blob)];$('referenceAudio').src=audioUrls[0];$('recordedAudio').src=audioUrls[1];}
async function captureTrial(seconds,signal){
 const ctx=context,sourceStream=stream,before=snapshot(ctx,sourceStream),events=[];let recorder,completed=false;
 try{
  recorder=await createPcmRecorder(ctx,sourceStream,{signal,onDiagnostic:event=>events.push(event)});checkSignal(signal);
  let blob;const done=new Promise((resolve,reject)=>{recorder.ondataavailable=e=>blob=e.data;recorder.onstop=resolve;recorder.onerror=()=>reject(new Error('PCM録音エラー'));});done.catch(()=>{});
  const captureStart=ctx.currentTime;recorder.start();const anchor=ctx.currentTime+.06,relative=[1,seconds/2,seconds-1.3],markerTimes=relative.map(t=>anchor+t),reference=makeClick(ctx.sampleRate);
  const refBuffer=ctx.createBuffer(1,reference.length,ctx.sampleRate);refBuffer.copyToChannel(reference,0);
  for(const when of markerTimes){const source=ctx.createBufferSource(),gain=ctx.createGain();source.buffer=refBuffer;gain.gain.value=.12;source.connect(gain).connect(ctx.destination);source.start(when);source.onended=()=>{source.disconnect();gain.disconnect();};activeSources.push(source);}
  await wait(seconds+.12,signal,ctx);recorder.stop();
  await bounded(done,{signal,ms:5000,message:'PCM録音の終了応答がありません'});checkSignal(signal);
  const after=snapshot(ctx,sourceStream);if(fingerprint(before)!==fingerprint(after))throw new Error('録音中に入力経路・設定が変わったため測定無効');
  const decoded=await ctx.decodeAudioData(await blob.arrayBuffer());checkSignal(signal);
  const result=await analysis({samples:decoded.getChannelData(0).slice(),reference:reference.slice(),rate:ctx.sampleRate,firstPcmTime:recorder.startTime,markerTimes},signal);checkSignal(signal);
  const placement=explainPlacement({timelineStart:captureStart-anchor,contextStart:captureStart,firstPcmTime:recorder.startTime,legacyLatency:recorder.latency});
  const rawStart=Number.isFinite(recorder.startTime)?recorder.startTime-anchor:null;
  for(const m of result.markers)m.predictedLegacyResidualSeconds=m.detected?m.lagSeconds+placement.calculatedStart-rawStart:null;
  const refFull=ctx.createBuffer(1,Math.ceil((seconds+.12)*ctx.sampleRate),ctx.sampleRate);for(const t of relative)refFull.getChannelData(0).set(Float32Array.from(reference,x=>x*.12),Math.round(t*ctx.sampleRate));
  preview(blob,encodeWav(refFull,{bitDepth:24}));completed=true;
  return {...result,durationSeconds:seconds,before,after,events,timing:{captureStart,firstPcmTime:recorder.startTime,anchor,rawStart},existingPlacementPreview:placement,
   correctionAppliedToMeasurementSeconds:0,manualCorrectionMs:0,route:declaredRoute(),note:'未補正のPCMと予定クリック時刻を比較。既存補正は計算結果の表示のみで適用しない。'};
 }finally{stopSources();if(recorder){if(!completed&&recorder.state!=='inactive')recorder.stop();recorder.dispose();}}
}
async function perform(fn,{recordInterruption=false}={}){if(operation)return;const controller=new AbortController();operation=controller;for(const id of ['referenceAudio','recordedAudio']){$(id).pause();$(id).removeAttribute('src');$(id).load();}update();try{await fn(controller.signal);}catch(error){probePassed=false;$('status').textContent=error.message;if(recordInterruption&&currentSession){currentSession.interrupted=true;currentSession.error=error.message;persist();renderResults();}await release();}finally{if(operation===controller)operation=undefined;update();}}
$('connect').onclick=()=>perform(async signal=>{
 await release();checkSignal(signal);setAudioMode('play-and-record');$('status').textContent='マイクを接続しています…';
 const request=requestCapture({deviceId:$('input').value});request.then(value=>{if(signal.aborted)value.getTracks().forEach(t=>t.stop());},()=>{});
 const acquired=await bounded(request,{signal,ms:30000,message:'マイクの許可・接続が完了しませんでした'});if(signal.aborted){acquired.getTracks().forEach(t=>t.stop());checkSignal(signal);}stream=acquired;
 context=new (window.AudioContext||window.webkitAudioContext)({latencyHint:'interactive'});await bounded(context.resume(),{signal,ms:5000,message:'音声Contextを開始できませんでした'});checkSignal(signal);showSnapshot(snapshot(context,stream));
 const selected=$('input').value,devices=await bounded(navigator.mediaDevices.enumerateDevices(),{signal,ms:3000}).catch(()=>[]);checkSignal(signal);$('input').replaceChildren();const fallback=document.createElement('option');fallback.value='';fallback.textContent='ブラウザ既定';$('input').append(fallback);for(const d of devices.filter(d=>d.kind==='audioinput')){const option=document.createElement('option');option.value=d.deviceId;option.textContent=d.label||'名前取得不可';$('input').append(option);}$('input').value=selected;
 stream.getAudioTracks()[0].addEventListener('ended',()=>{if(stream)invalidate('マイクが切断されたため測定を停止しました');},{once:true});
 $('connection').textContent='接続済み。実際の入力名を確認してください。';$('status').textContent='音響結合の確認へ進んでください';
});
$('disconnect').onclick=()=>release();$('cancel').onclick=()=>{operation?.abort(abortError());release();};
for(const id of ['route','routeNote','input','duration','coupled','routeConfirmed'])$(id).addEventListener('change',()=>{probePassed=false;$('probeResult').textContent='条件変更のため音響結合を確認し直してください。';if(id==='input')release();update();});
$('probe').onclick=()=>perform(async signal=>{currentSession=undefined;$('status').textContent='クリックを3か所で録音しています…';const result=await captureTrial(6,signal);probePassed=result.accepted;$('probeResult').textContent=probePassed?'3つのクリックを検出。音響結合を確認できました。同じ条件で5回測定できます。':'測定不可：'+result.reason+'。発音部の位置・実際の入力マイク・音量を確認してください。スピーカーへ切り替えた値はEarPodsへ流用できません。';$('status').textContent=probePassed?'測定準備完了':'5回測定は開始できません';currentSession={id:crypto.randomUUID(),createdAt:new Date().toISOString(),environment:environment(),route:declaredRoute(),durationSeconds:Number($('duration').value),protocol:'steady-context-acoustic-click-v1',searchWindowSeconds:[-.05,1.5],probe:result,trials:[]};sessions.push(currentSession);sessions=sessions.slice(-10);persist();renderResults();});
$('measure').onclick=()=>perform(async signal=>{
 if(!probePassed||!currentSession)throw new Error('先に音響結合を確認してください');
 if(currentSession.trials.length){currentSession={...currentSession,id:crypto.randomUUID(),createdAt:new Date().toISOString(),trials:[],interrupted:false,error:null};sessions.push(currentSession);sessions=sessions.slice(-10);}
 for(let i=0;i<5;i++){checkSignal(signal);$('status').textContent=`${i+1} / 5 回目を録音中（${currentSession.durationSeconds}秒）。画面を前面に保ってください。`;const trial=await captureTrial(currentSession.durationSeconds,signal);currentSession.trials.push(trial);persist();renderResults();if(!trial.accepted){probePassed=false;$('status').textContent='測定無効：'+trial.reason+'。条件を確認し、音響結合の確認からやり直してください。';return;}}
 $('status').textContent='5回の測定が完了しました。補正値は変更していません。';
},{recordInterruption:true});
function renderResults(){const session=currentSession||sessions.at(-1),trials=session?.trials||[];$('trials').replaceChildren();for(let i=0;i<5;i++){const trial=trials[i],tr=document.createElement('tr'),values=[String(i+1),...[0,1,2].map(j=>trial?ms(trial.markers[j]?.lagSeconds):'未測定'),trial?.accepted?ms(trial.markers[2].lagSeconds-trial.markers[0].lagSeconds):'—',trial?(trial.accepted?'有効':'無効'):'未測定'];for(const value of values){const td=document.createElement('td');td.textContent=value;tr.append(td);}$('trials').append(tr);}const result=summarizeTrials(trials),stats=result.statistics;$('summary').textContent=stats?`${result.complete?'5回完了':'暫定結果'}：有効 ${result.accepted} / 5回。平均 ${ms(stats.mean)} ／ 標本標準偏差 ${ms(stats.standardDeviation)} ／ 最小 ${ms(stats.min)} ／ 最大 ${ms(stats.max)}。${session?.route?.declared==='speaker'?'スピーカー条件です。EarPods補正へ流用不可。':'出力経路は自己申告でありAPI検証済みではありません。'}`:'有効な測定はまだありません。';$('measurementJson').textContent=JSON.stringify(session?{...session,summary:result}:null,null,2);}
function renderLogs(){const logs=loadRecordingLogs();$('recordingLogs').replaceChildren();if(!logs.length){$('recordingLogs').textContent='診断ログはありません。';return;}for(const log of [...logs].reverse()){const details=document.createElement('details'),summary=document.createElement('summary');summary.textContent=`${log.start?.at||''} · ${log.start?.input?.label||'マイク名取得不可'}`;details.append(summary);const fields=document.createElement('div'),p=log.placement||{},read=log.events?.find(e=>e.type==='latency-read'&&e.phase==='start')||log.events?.find(e=>e.type==='latency-read');rowList(fields,[['Context / sampleRate',`${log.start?.contextId} / ${log.start?.state} / ${log.start?.sampleRate} Hz`],['入力latency（準備時）',formatMs(log.prepared?.inputLatency)],['出力latency（準備時）',formatMs(log.prepared?.outputLatency)],['入力latency（録音開始時）',formatMs(log.start?.inputLatency)],['出力latency（録音開始時）',formatMs(log.start?.outputLatency)],['補正計算時の入力latency',formatMs(reading(read?.input))],['補正計算時の出力latency',formatMs(reading(read?.output))],['補正計算時の報告合計',`${ms(read?.sum)}（取得不可を既存式が0扱いした合計・実測ではない）`],['自動補正の実適用値',ms(p.automaticAppliedSeconds)],['0.5秒超の破棄',p.overHalfSecondDiscarded?'該当：既存処理が補正を0にしました':'該当なし'],['手動補正',`${p.manualMs??0} ms`],['録音開始Context時刻',`${p.contextStart} 秒`],['最初のPCM Context時刻',p.firstPcmTime===null?'取得不可':`${p.firstPcmTime} 秒`],['保存開始位置',`${p.savedStart} 秒`],['最終観測位置＋手動補正',`${(log.currentStart??p.savedStart)+(p.manualMs||0)/1000} 秒`]]);details.append(fields);const pre=document.createElement('pre');pre.textContent=JSON.stringify(log,null,2);details.append(pre);$('recordingLogs').append(details);}}
$('refreshLogs').onclick=renderLogs;
$('download').onclick=()=>{const report={format:'pocket-booth-latency-diagnostics',version:1,exportedAt:new Date().toISOString(),sessions:sessions.map(s=>({...s,summary:summarizeTrials(s.trials||[])})),recordings:loadRecordingLogs(),note:'音声なし。測定結果を録音補正へ適用していません。'},url=URL.createObjectURL(new Blob([JSON.stringify(report,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='PocketBooth-latency-diagnostics.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
$('clear').onclick=()=>{try{localStorage.removeItem(LOG_KEY);localStorage.removeItem(SESSION_KEY);sessions=[];currentSession=undefined;probePassed=false;renderLogs();renderResults();update();$('storageStatus').textContent='診断ログだけを削除しました。曲のデータは変更していません。';}catch{$('storageStatus').textContent='診断ログを削除できませんでした';}};
navigator.mediaDevices?.addEventListener('devicechange',()=>{if(stream)invalidate('音声機器の変更を検知。経路を確認し直してください。');});
document.addEventListener('visibilitychange',()=>{if(document.hidden)invalidate('画面を離れたため測定を中断・マイクを解放しました。');});
window.addEventListener('pagehide',()=>{operation?.abort(abortError());release();for(const url of audioUrls)URL.revokeObjectURL(url);});
renderLogs();renderResults();update();$('storageStatus').textContent=lastStorageError;
